head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt50210";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50210.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_61_onclick
 * @description img_61 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_61_onclick = function(e){
    try {
        $c.win.moveUrl('/filing/editClass.do')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50210.img_61_onclick' }); }
};

/**
 * @method
 * @name img_62_onclick
 * @description img_62 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_62_onclick = async function(e){
    try {
        await scwin.popInsert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50210.img_62_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

/**
 * @method
 * @name tx_fn_Delete_xhr
 * @description Delete xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Delete_xhr", unresolved: "action:self_submit:tx_fn_Delete_xhr" };
};

/**
 * @method
 * @name tx_fn_Up_xhr
 * @description Up xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Up_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Up_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Up_xhr", unresolved: "action:self_submit:tx_fn_Up_xhr" };
};

/**
 * @method
 * @name tx_fn_Down_xhr
 * @description Down xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Down_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Down_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Down_xhr", unresolved: "action:self_submit:tx_fn_Down_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "findEditMidclasses");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_List_xhr());
};

/**
 * @method
 * @name popInsert
 * @description pop Insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popInsert = async function () {
    const _url = "/filing/editClass.do?method=prepareUpdateEditMidclass&upEditClssCd=" + dma_editUpclass.get("editClssCd") + "&mode=create";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "midclassPop", popupName: "midclassPop" }, {});
};

/**
 * @method
 * @name popModify
 * @description pop Modify 처리
 * @param {String} editClssCd editClssCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popModify = async function (editClssCd) {
    const _url = "/filing/editClass.do?method=prepareUpdateEditMidclass&editClssCd=" + editClssCd + "&upEditClssCd=" + dma_editUpclass.get("editClssCd") + "&mode=update";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "midclassPop", popupName: "midclassPop", width: "500", height: "340" }, {});
};

/**
 * @method
 * @name deleteListXhrReq
 * @description delete List Xhr Req 처리
 * @param {String} editClssCd editClssCd
 * @param {String} editClssNm editClssNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteListXhrReq = async function (editClssCd, editClssNm) {
    const _confirm = await $c.win.confirm("편집기중분류 '" + editClssNm + "'를\n삭제하시겠습니까?");
    if (!_confirm) {
        return;
    }
    $c.util.getComponent('dma_ListXhrReq').set('editClssCd', editClssCd);
    scwin.form_listForm.action = "/filing/editClass.do";
    $c.util.getComponent('dma_ListXhrReq').set('method', "deleteEditMidclass");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_Delete_xhr());
};

/**
 * @method
 * @name up
 * @description up 처리
 * @param {String} editClssCd editClssCd
 * @param {*} screnDpOrdNo screnDpOrdNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.up = async function (editClssCd, screnDpOrdNo) {
    $c.util.getComponent('dma_ListXhrReq').set('editClssCd', editClssCd);
    $c.util.getComponent('dma_ListXhrReq').set('screnDpOrdNo', screnDpOrdNo);
    $c.util.getComponent('dma_ListXhrReq').set('direction', "up");
    $c.util.getComponent('dma_ListXhrReq').set('method', "updateEditClassOrdNo");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_Up_xhr());
};

/**
 * @method
 * @name down
 * @description down 처리
 * @param {String} editClssCd editClssCd
 * @param {*} screnDpOrdNo screnDpOrdNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.down = async function (editClssCd, screnDpOrdNo) {
    $c.util.getComponent('dma_ListXhrReq').set('editClssCd', editClssCd);
    $c.util.getComponent('dma_ListXhrReq').set('screnDpOrdNo', screnDpOrdNo);
    $c.util.getComponent('dma_ListXhrReq').set('direction', "down");
    $c.util.getComponent('dma_ListXhrReq').set('method', "updateEditClassOrdNo");
    $c.util.getComponent('txt_listDiv').setValue(await scwin.tx_fn_Down_xhr());
};
